import { z } from 'zod';
import { RoomId } from './messages';

export const ROOMS_PATH = '/api/rooms';

/** Seconds a `room:<id>` key lives in KV without being renewed (RoomDO renews on join / leave). */
export const ROOM_KV_TTL_SECONDS = 300;

/** Length of a room id generated by `POST /api/rooms` (RoomId itself allows 4-12). */
export const GENERATED_ROOM_ID_LENGTH = 6;

/**
 * Metadata stored on each `room:<id>` KV key. KV is eventually consistent (~60s),
 * so this is for the lobby list only: RoomDO alone decides whether a room is full.
 */
export const RoomKvMetadata = z.object({
  players: z.number().int().min(0),
  max: z.number().int().min(1),
  createdAt: z.number().int(),
});
export type RoomKvMetadata = z.infer<typeof RoomKvMetadata>;

/** One row of `GET /api/rooms`. */
export const RoomSummary = RoomKvMetadata.extend({ roomId: RoomId });
export type RoomSummary = z.infer<typeof RoomSummary>;

/** Response body of `POST /api/rooms` (201). */
export const CreateRoomResponse = z.object({ roomId: RoomId });
export type CreateRoomResponse = z.infer<typeof CreateRoomResponse>;

/** Response body of `GET /api/rooms` (200). Full rooms are already filtered out. */
export const ListRoomsResponse = z.object({ rooms: z.array(RoomSummary) });
export type ListRoomsResponse = z.infer<typeof ListRoomsResponse>;

/** `{ error }` codes of the rooms HTTP API (separate from the WebSocket `ErrorCode`). */
export const RoomsApiErrorCode = z.enum(['RATE_LIMITED', 'ROOM_ID_UNAVAILABLE']);
export type RoomsApiErrorCode = z.infer<typeof RoomsApiErrorCode>;
